{
  "expo": {
    "name": "Apex Factory",
    "slug": "apex-factory",
    "version": "1.0.0",
    "orientation": "portrait",
    "icon": "./assets/images/icon.png",
    "scheme": "apexfactory",
    "buildCacheProvider": {
      "plugin": "../../tools/expo-build-cache/provider.plugin.js"
    },
    "userInterfaceStyle": "automatic",
    "backgroundColor": "#0A0A0C",
    "ios": {
      "bundleIdentifier": "com.callstack.apexfactory",
      "supportsTablet": true,
      "infoPlist": {
        "NSAppTransportSecurity": {
          "NSAllowsArbitraryLoads": false,
          "NSAllowsLocalNetworking": true
        },
        "NSLocalNetworkUsageDescription": "Apex Factory downloads new features from the Callstack booth laptop on this Wi-Fi network.",
        "NSCameraUsageDescription": "Apex Factory uses the camera for booth features you try, like scanning a QR code or taking a photo. Nothing is uploaded."
      }
    },
    "android": {
      "package": "com.callstack.apexfactory",
      "adaptiveIcon": {
        "backgroundColor": "#0A0A0C",
        "foregroundImage": "./assets/images/android-icon-foreground.png",
        "backgroundImage": "./assets/images/android-icon-background.png",
        "monochromeImage": "./assets/images/android-icon-monochrome.png"
      },
      "predictiveBackGestureEnabled": false,
      "permissions": ["android.permission.CAMERA"],
      "blockedPermissions": [
        "android.permission.RECORD_AUDIO",
        "android.permission.ACCESS_BACKGROUND_LOCATION",
        "android.permission.READ_MEDIA_AUDIO"
      ]
    },
    "plugins": [
      "expo-router",
      [
        "expo-splash-screen",
        {
          "backgroundColor": "#0A0A0C",
          "image": "./assets/images/splash-icon.png",
          "imageWidth": 96
        }
      ],
      [
        "@hot-updater/react-native",
        {
          "channel": "production"
        }
      ],
      [
        "expo-build-properties",
        {
          "android": {
            "usesCleartextTraffic": true
          }
        }
      ],
      "./plugins/with-android-build-memory",
      [
        "@appduct/react-native",
        {
          "trust": "link",
          "allowPrivateLanOnly": true
        }
      ],
      "expo-sharing",
      [
        "expo-image-picker",
        {
          "photosPermission": "Apex Factory opens your photo library only when you pick a photo for a booth feature you try.",
          "cameraPermission": "Apex Factory uses the camera for booth features you try, like scanning a QR code or taking a photo. Nothing is uploaded.",
          "microphonePermission": false
        }
      ],
      [
        "expo-media-library",
        {
          "photosPermission": "Apex Factory opens your photo library only when you pick a photo for a booth feature you try.",
          "savePhotosPermission": "Apex Factory saves pictures you create in a booth feature to your photo library.",
          "granularPermissions": ["photo"]
        }
      ],
      [
        "expo-location",
        {
          "locationWhenInUsePermission": "Apex Factory uses your location while the app is open, for booth features you try such as showing where you are on a map.",
          "locationAlwaysAndWhenInUsePermission": false,
          "locationAlwaysPermission": false,
          "motionUsagePermission": "Apex Factory reads motion sensors (steps, movement) for booth features you try, such as a step counter."
        }
      ],
      [
        "expo-calendar",
        {
          "calendarPermission": "Apex Factory reads and adds calendar events only for booth features you try, such as saving a reactCon session to your calendar.",
          "remindersPermission": false
        }
      ],
      [
        "expo-sensors",
        {
          "motionPermission": "Apex Factory reads motion sensors (steps, movement) for booth features you try, such as a step counter."
        }
      ],
      "./plugins/with-local-notifications-only",
      ["expo-notifications", {}],
      "./plugins/with-android-maps-key",
      "react-native-maps"
    ],
    "experiments": {
      "typedRoutes": true,
      "reactCompiler": true
    }
  }
}

// More heap for the Android release build.
//
// With Skia, VisionCamera, MLKit and the rest for four ABIs, the release APK
// is over 200 MB, and Gradle's packaging step ran out of memory with the
// template's 2 GB (`OutOfMemoryError` in :app:packageRelease). 4 GB is
// enough on the booth laptop.
const { withGradleProperties } = require("expo/config-plugins");

const JVM_ARGS = "-Xmx4096m -XX:MaxMetaspaceSize=1024m";

module.exports = function withAndroidBuildMemory(config) {
  return withGradleProperties(config, (mod) => {
    const props = mod.modResults.filter(
      (item) => !(item.type === "property" && item.key === "org.gradle.jvmargs"),
    );
    props.push({ type: "property", key: "org.gradle.jvmargs", value: JVM_ARGS });
    mod.modResults = props;
    return mod;
  });
};

// Google Maps API key for react-native-maps on Android, read from the
// environment at prebuild time: GOOGLE_MAPS_ANDROID_API_KEY.
//
// iOS uses Apple Maps (no key). Android's map is Google Maps, which needs a
// key in the manifest. Without that meta-data entry at all, the Maps SDK
// throws "API key not found" and the app crashes the moment a <MapView>
// mounts; with an invalid key it only shows an empty grid. So a build without
// the variable gets a placeholder: it builds, nothing crashes, and Android maps
// stay blank until a binary is built with a real key (restricted to the
// package name and signing certificate in Google Cloud). The key is a build
// input like the EXPO_PUBLIC_* URLs; never commit it.
//
// List it BEFORE "react-native-maps" in app.json (Expo runs the mods of earlier
// plugins last; react-native-maps removes the entry when it has no key). See
// docs/internal/NATIVE-CAPABILITIES.md.
const { AndroidConfig, withAndroidManifest } = require("expo/config-plugins");

const META_DATA = "com.google.android.geo.API_KEY";
const PLACEHOLDER = "maps-key-not-configured";

module.exports = function withAndroidMapsKey(config) {
  return withAndroidManifest(config, (mod) => {
    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(mod.modResults);
    const key = process.env.GOOGLE_MAPS_ANDROID_API_KEY?.trim() || PLACEHOLDER;
    AndroidConfig.Manifest.addMetaDataItemToMainApplication(app, META_DATA, key);
    return mod;
  });
};

// The booth binary schedules LOCAL notifications only (expo-notifications).
//
// expo-notifications' own config plugin, which Expo also applies automatically
// whenever the package is installed, adds the iOS `aps-environment`
// entitlement for push. Signing an app with that entitlement needs a
// provisioning profile with the Push Notifications capability, which a
// personal team cannot have and the booth does not use (there are no APNs or
// FCM credentials anywhere). Local notifications need no entitlement, so this
// plugin removes it again. List it BEFORE "expo-notifications" in app.json:
// Expo runs the mods of earlier plugins last, so this one gets the final word.
//
// Push notifications are not in the binary: docs/internal/NATIVE-CAPABILITIES.md.
const { withEntitlementsPlist } = require("expo/config-plugins");

module.exports = function withLocalNotificationsOnly(config) {
  return withEntitlementsPlist(config, (mod) => {
    delete mod.modResults["aps-environment"];
    return mod;
  });
};

